import{_ as a,o,c as t,a0 as d}from"./chunks/framework.C4u0TEY0.js";const x=JSON.parse('{"title":"DEX 解释器","description":"","frontmatter":{},"headers":[],"relativePath":"zh/internals/dex.md","filePath":"zh/internals/dex.md"}'),r={name:"zh/internals/dex.md"};function c(i,e,n,l,s,h){return o(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="dex-解释器" tabindex="-1">DEX 解释器 <a class="header-anchor" href="#dex-解释器" aria-label="Permalink to &quot;DEX 解释器&quot;">​</a></h1><h2 id="文件结构" tabindex="-1">文件结构 <a class="header-anchor" href="#文件结构" aria-label="Permalink to &quot;文件结构&quot;">​</a></h2><p>DEX 文件由一个头和若干张表组成：字符串、类型、原型、字段、方法和类定义。apk.js 一次读完所有表，保留可按索引访问的数组。多 dex 的 APK（<code>classes2.dex</code>、<code>classes3.dex</code> 等）会加载到同一个类注册表，跨 dex 的引用能够正常解析。</p><h2 id="字节码执行" tabindex="-1">字节码执行 <a class="header-anchor" href="#字节码执行" aria-label="Permalink to &quot;字节码执行&quot;">​</a></h2><p><code>DexInterpreter.execute</code> 按方法的 <code>registersSize</code> 分配寄存器文件，把参数复制到尾部，再用程序计数器遍历指令流。</p><p>指令按 8 位 opcode 解码。调用指令（<code>0x6e</code>–<code>0x78</code>）读出参数寄存器、解析方法引用，把调用交给 <code>JavaVM.invoke</code>。返回值放进 <code>pendingResult</code>，由下一条 <code>move-result</code> 取走。</p><h2 id="方法解析" tabindex="-1">方法解析 <a class="header-anchor" href="#方法解析" aria-label="Permalink to &quot;方法解析&quot;">​</a></h2><p><code>JavaVM.invoke</code> 的解析顺序：</p><ol><li>类上注册的 native 定义，即 Framework 和 Java 核心类。</li><li>解析到的类上的 DEX 方法，沿父类链向上查找。</li><li><code>invoke-interface</code> 对应的接口方法。</li></ol><p>调用未实现的 native 方法会抛 <code>VMRuntimeError</code>，再转成应用可以捕获的 Java 异常。</p><h2 id="异常" tabindex="-1">异常 <a class="header-anchor" href="#异常" aria-label="Permalink to &quot;异常&quot;">​</a></h2><p>处理器来自方法的 catch 表。调用抛错时，解释器在当前 PC 上查表找匹配的处理器，把 PC 移到处理器入口，并把异常对象写进处理器的寄存器。没有匹配项时，异常沿栈向上传播。</p><h2 id="字段访问" tabindex="-1">字段访问 <a class="header-anchor" href="#字段访问" aria-label="Permalink to &quot;字段访问&quot;">​</a></h2><p>字段通过类注册表解析。实例字段存在每个对象的映射里，键为 <code>classDesc-&gt;name:type</code>；继承字段沿类链查找。静态字段挂在运行时类上，只初始化一次。</p>',14)])])}const u=a(r,[["render",c]]);export{x as __pageData,u as default};
